        "items": {
          "status": "resolved",
          "literal": "=With(\n    {\n        _textoDescricao: Trim(TextInput11_1.Text)\n    },\n    With(\n        {\n            _dadosFiltrados:\n                Filter(\n                    NOVACOTACAO As NC,\n\n                    // DESCRIÇÃO\n                    IsBlank(_textoDescricao) ||\n                        _textoDescricao in Coalesce(NC.DESCRICAO, \"\"),\n\n                    // ID\n                    IsBlank(ComboBox37_10.Selected.ID) ||\n                        NC.ID = ComboBox37_10.Selected.ID,\n\n                    // FILIAL\n                    IsBlank(ComboBox67_18.Selected.FILIAL) ||\n                        NC.FILIAL = ComboBox67_18.Selected.FILIAL,\n\n                    // ETAPA\n                    IsBlank(ComboBox11_28.Selected.Value) ||\n                        NC.ETAPA = ComboBox11_28.Selected.Value,\n\n                    // STATUS\n                    IsBlank(ComboBox67_19.Selected.Value) ||\n                        NC.STATUS = ComboBox67_19.Selected.Value\n                )\n        },\n        If(\n            IsBlank(ComboBox28_9.Selected.Campo),\n            SortByColumns(\n                _dadosFiltrados,\n                \"Created\",\n                SortOrder.Descending\n            ),\n            SortByColumns(\n                _dadosFiltrados,\n                ComboBox28_9.Selected.Campo,\n                ComboBox28_9.Selected.Ordem\n            )\n        )\n    )\n)"
        },
        "default": {
          "status": "not-declared",
          "literal": null
        },
        "sort": {
          "status": "resolved",
          "literals": [
            "SortByColumns(\n                _dadosFiltrados,\n                \"Created\",\n                SortOrder.Descending\n            )",
            "SortByColumns(\n                _dadosFiltrados,\n                ComboBox28_9.Selected.Campo,\n                ComboBox28_9.Selected.Ordem\n            )"
          ]
        },
        "filter": {
          "status": "resolved",
          "literals": [
            "Filter(\n                    NOVACOTACAO As NC,\n\n                    // DESCRIÇÃO\n                    IsBlank(_textoDescricao) ||\n                        _textoDescricao in Coalesce(NC.DESCRICAO, \"\"),\n\n                    // ID\n                    IsBlank(ComboBox37_10.Selected.ID) ||\n                        NC.ID = ComboBox37_10.Selected.ID,\n\n                    // FILIAL\n                    IsBlank(ComboBox67_18.Selected.FILIAL) ||\n                        NC.FILIAL = ComboBox67_18.Selected.FILIAL,\n\n                    // ETAPA\n                    IsBlank(ComboBox11_28.Selected.Value) ||\n                        NC.ETAPA = ComboBox11_28.Selected.Value,\n\n                    // STATUS\n                    IsBlank(ComboBox67_19.Selected.Value) ||\n                        NC.STATUS = ComboBox67_19.Selected.Value\n                )"
          ]
        }
